attributes.visState:
{"title": "[Tropobeat] Episodes: list, 30 days", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": {
  "left": 20,
  "right": 20,
  "top": 18,
  "bottom": 12
 },
 "background": "#0F1F2C",
 "config": {
  "view": {
   "stroke": null
  },
  "text": {
   "font": "\"Inter\",\"Segoe UI\",system-ui,sans-serif",
   "fill": "#E4EDF3"
  },
  "axis": {
   "domain": false,
   "ticks": false,
   "labelColor": "#8DA2B2",
   "labelFont": "ui-monospace,Menlo,Consolas,monospace",
   "labelFontSize": 10.5,
   "gridColor": "#1B3042"
  }
 },
 "title": {
  "text": "Episodes, last 30 days",
  "subtitle": "NEWEST FIRST · CLICK ONE TO SHOW ITS TIMELINE AND DECISIONS BELOW",
  "anchor": "start",
  "frame": "group",
  "offset": 12,
  "color": "#E4EDF3",
  "font": "\"Barlow Condensed\",\"Roboto Condensed\",\"Arial Narrow\",sans-serif",
  "fontSize": 22,
  "fontWeight": 600,
  "subtitleColor": "#8DA2B2",
  "subtitleFont": "ui-monospace,Menlo,Consolas,monospace",
  "subtitleFontSize": 11,
  "subtitlePadding": 4
 },
 "signals": [
  {
   "name": "stateLabel",
   "value": {
    "cci_confirmed": "CCI CONFIRMED",
    "dual_unexplained": "DUAL UNEXPLAINED",
    "dual_ducting_unknown": "DUCTING UNKNOWN",
    "unpaired": "UNPAIRED",
    "single_side": "SINGLE SIDE",
    "clear": "CLEAR"
   }
  },
  {
   "name": "stateFill",
   "value": {
    "cci_confirmed": "#FF6B5E",
    "dual_unexplained": "#E0A458",
    "dual_ducting_unknown": "#A88A4A",
    "unpaired": "#5D7C91",
    "single_side": "#5D7C91",
    "clear": "#13283A"
   }
  },
  {
   "name": "stateInk",
   "value": {
    "cci_confirmed": "#2A0F0C",
    "dual_unexplained": "#2B1B05",
    "dual_ducting_unknown": "#1E1606",
    "unpaired": "#E4EDF3",
    "single_side": "#E4EDF3",
    "clear": "#8DA2B2"
   }
  },
  {
   "name": "sevState",
   "value": {
    "0": "clear",
    "1": "single_side",
    "2": "unpaired",
    "3": "dual_ducting_unknown",
    "4": "dual_unexplained",
    "5": "cci_confirmed"
   }
  },
  {
   "name": "rowh",
   "value": 40
  },
  {
   "name": "head",
   "value": 22
  },
  {
   "name": "showId",
   "update": "width >= 1250"
  },
  {
   "name": "idW",
   "update": "showId ? 200 : 0"
  },
  {
   "name": "infX",
   "update": "max(700, width - 580 - idW)"
  },
  {
   "name": "showInfra",
   "update": "width >= 1100"
  },
  {
   "name": "nOpen",
   "update": "length(data('openRows'))"
  },
  {
   "name": "pinH",
   "update": "nOpen ? nOpen * rowh + 10 : 0"
  },
  {
   "name": "areaH",
   "update": "max(rowh * 2, height - head - 26 - pinH)"
  },
  {
   "name": "nRows",
   "update": "length(data('closedAll'))"
  },
  {
   "name": "maxScroll",
   "update": "max(0, nRows * rowh - areaH)"
  },
  {
   "name": "dragFrom",
   "value": null,
   "on": [
    {
     "events": "@thumb:mousedown",
     "update": "{y: y(), s: scrollY}"
    },
    {
     "events": "window:mouseup",
     "update": "null"
    }
   ]
  },
  {
   "name": "scrollY",
   "value": 0,
   "on": [
    {
     "events": "wheel!",
     "update": "clamp(scrollY + event.deltaY * (event.deltaMode == 1 ? rowh / 2 : event.deltaMode == 2 ? areaH : 1), 0, maxScroll)"
    },
    {
     "events": "window:mousemove",
     "update": "dragFrom ? clamp(dragFrom.s + (y() - dragFrom.y) * nRows * rowh / areaH, 0, maxScroll) : scrollY"
    },
    {
     "events": {
      "signal": "maxScroll"
     },
     "update": "min(scrollY, maxScroll)"
    }
   ]
  },
  {
   "name": "firstVis",
   "update": "nRows ? floor(scrollY / rowh) + 1 : 0"
  },
  {
   "name": "lastVis",
   "update": "min(nRows, floor((scrollY + areaH) / rowh))"
  },
  {
   "name": "selected",
   "update": "length(data('sel')) == 1 ? data('sel')[0].key : null"
  },
  {
   "name": "chosen",
   "value": null,
   "on": [
    {
     "events": "@row:click",
     "update": "{d: datum, at: now()}"
    },
    {
     "events": "@rowPinned:click",
     "update": "{d: datum, at: now()}"
    }
   ]
  },
  {
   "name": "act",
   "update": "chosen ? [kibanaSetTimeFilter(chosen.d.from, chosen.d.to), kibanaRemoveAllFilters(), kibanaAddFilter({bool: {filter: [{term: {'tropobeat.lrf_codes': chosen.d.lrf}}, {term: {'tropobeat.rf_channels': chosen.d.rf}},{bool: {should: [{range: {'@timestamp': {gte: chosen.d.from, lte: chosen.d.to, format: 'epoch_millis'}}}, {term: {'metricset.name': 'weather'}}], minimum_should_match: 1}},{bool: {should: [{term: {'tropobeat.correlation.episode.id': chosen.d.key}},{bool: {must_not: {exists: {field: 'tropobeat.correlation.episode.id'}}}}], minimum_should_match: 1}}]}}, 'tropobeat-*', 'Episode ' + (chosen.d.station ? chosen.d.station + ' · ' : '') + chosen.d.lrf + ' RF ' + chosen.d.rf + ' · ' + timeFormat(chosen.d.start, '%d %b %H:%M'))] : null"
  }
 ],
 "data": [
  {
   "name": "epRaw",
   "format": {
    "property": "aggregations.e.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "query": {
      "bool": {
       "must": [
        {
         "term": {
          "metricset.name": "correlation"
         }
        },
        {
         "range": {
          "@timestamp": {
           "gte": "now-30d"
          }
         }
        }
       ]
      }
     },
     "aggs": {
      "e": {
       "terms": {
        "field": "tropobeat.correlation.episode.id",
        "size": 2000,
        "order": {
         "start": "desc"
        }
       },
       "aggs": {
        "start": {
         "min": {
          "field": "@timestamp"
         }
        },
        "last": {
         "max": {
          "field": "@timestamp"
         }
        },
        "peak": {
         "max": {
          "field": "tropobeat.correlation.severity"
         }
        },
        "dur": {
         "max": {
          "field": "tropobeat.correlation.episode.duration_s"
         }
        },
        "top": {
         "top_hits": {
          "size": 1,
          "sort": [
           {
            "@timestamp": "desc"
           }
          ],
          "_source": false,
          "fields": [
           "tropobeat.correlation.sides.a.instances.card_label",
           "tropobeat.correlation.sides.a.instances.frame_label",
           "tropobeat.correlation.sides.a.instances.id",
           "tropobeat.correlation.sides.b.instances.card_label",
           "tropobeat.correlation.sides.b.instances.frame_label",
           "tropobeat.correlation.sides.b.instances.id",
           "tropobeat.station_call_signs",
           "tropobeat.lrf_codes",
           "tropobeat.rf_channels",
           "tropobeat.correlation.kind",
           "tropobeat.correlation.ducting.strongest.call_sign",
           "tropobeat.correlation.ducting.strongest.distance_mi"
          ]
         }
        },
        "cci": {
         "filter": {
          "term": {
           "tropobeat.correlation.state": "cci_confirmed"
          }
         },
         "aggs": {
          "top": {
           "top_hits": {
            "size": 1,
            "sort": [
             {
              "@timestamp": "desc"
             }
            ],
            "_source": false,
            "fields": [
             "tropobeat.correlation.sides.a.instances.card_label",
             "tropobeat.correlation.sides.a.instances.frame_label",
             "tropobeat.correlation.sides.a.instances.id",
             "tropobeat.correlation.sides.b.instances.card_label",
             "tropobeat.correlation.sides.b.instances.frame_label",
             "tropobeat.correlation.sides.b.instances.id",
             "tropobeat.station_call_signs",
             "tropobeat.lrf_codes",
             "tropobeat.rf_channels",
             "tropobeat.correlation.kind",
             "tropobeat.correlation.ducting.strongest.call_sign",
             "tropobeat.correlation.ducting.strongest.distance_mi"
            ]
           }
          }
         }
        }
       }
      }
     }
    }
   }
  },
  {
   "name": "allRows",
   "source": "epRaw",
   "transform": [
    {
     "type": "formula",
     "as": "start",
     "expr": "datum.start.value"
    },
    {
     "type": "formula",
     "as": "last",
     "expr": "datum.last.value"
    },
    {
     "type": "formula",
     "as": "lrf",
     "expr": "datum.top.hits.hits[0].fields['tropobeat.lrf_codes'][0]"
    },
    {
     "type": "formula",
     "as": "station",
     "expr": "datum.top.hits.hits[0].fields['tropobeat.station_call_signs'] ? join(datum.top.hits.hits[0].fields['tropobeat.station_call_signs'], ' / ') : ''"
    },
    {
     "type": "formula",
     "as": "rf",
     "expr": "datum.top.hits.hits[0].fields['tropobeat.rf_channels'][0]"
    },
    {
     "type": "formula",
     "as": "open",
     "expr": "datum.top.hits.hits[0].fields['tropobeat.correlation.kind'][0] != 'clear' && now() - datum.last < 360000"
    },
    {
     "type": "formula",
     "as": "state",
     "expr": "sevState[datum.peak.value] || 'clear'"
    },
    {
     "type": "formula",
     "as": "from",
     "expr": "datum.start - 300000"
    },
    {
     "type": "formula",
     "as": "to",
     "expr": "datum.open ? now() + 3600000 : datum.last + 180000"
    },
    {
     "type": "formula",
     "as": "secs",
     "expr": "datum.open ? (now() - datum.start) / 1000 : datum.dur.value || 0"
    },
    {
     "type": "formula",
     "as": "durText",
     "expr": "(datum.open ? 'open · ' : '') + (datum.secs) >= 3600 ? floor((datum.secs) / 3600) + ' h ' + floor((datum.secs) % 3600 / 60) + ' m' : (datum.secs) >= 60 ? floor((datum.secs) / 60) + ' m ' + floor((datum.secs) % 60) + ' s' : floor((datum.secs)) + ' s'"
    },
    {
     "type": "formula",
     "as": "cf",
     "expr": "datum.cci.top.hits.hits[0] ? datum.cci.top.hits.hits[0].fields : null"
    },
    {
     "type": "formula",
     "as": "who",
     "expr": "datum.cf && datum.cf['tropobeat.correlation.ducting.strongest.call_sign'] ? datum.cf['tropobeat.correlation.ducting.strongest.call_sign'][0] + ', ' + round(datum.cf['tropobeat.correlation.ducting.strongest.distance_mi'][0]) + ' mi' : '–'"
    },
    {
     "type": "formula",
     "as": "infA",
     "expr": "datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.card_label'] ? replace(replace(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.card_label'][0], regexp('^[^-]+- '), ''), regexp(' - [AB]$'), '') + (datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.frame_label'] ? ' · frame ' + replace(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.frame_label'][0], regexp(' - [AB]$'), '') : '') + (datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.id'] ? ' · ' + datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.id'][0] + (length(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.id']) > 1 ? ' +' + (length(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.a.instances.id']) - 1) : '') : '') : 'no input on this side'"
    },
    {
     "type": "formula",
     "as": "infB",
     "expr": "datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.card_label'] ? replace(replace(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.card_label'][0], regexp('^[^-]+- '), ''), regexp(' - [AB]$'), '') + (datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.frame_label'] ? ' · frame ' + replace(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.frame_label'][0], regexp(' - [AB]$'), '') : '') + (datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.id'] ? ' · ' + datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.id'][0] + (length(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.id']) > 1 ? ' +' + (length(datum.top.hits.hits[0].fields['tropobeat.correlation.sides.b.instances.id']) - 1) : '') : '') : 'no input on this side'"
    },
    {
     "type": "window",
     "sort": {
      "field": "start",
      "order": "descending"
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "n"
     ]
    }
   ]
  },
  {
   "name": "openRows",
   "source": "allRows",
   "transform": [
    {
     "type": "filter",
     "expr": "datum.open"
    },
    {
     "type": "window",
     "sort": {
      "field": "start",
      "order": "descending"
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "m"
     ]
    },
    {
     "type": "formula",
     "as": "y",
     "expr": "(datum.m - 1) * rowh"
    }
   ]
  },
  {
   "name": "closedAll",
   "source": "allRows",
   "transform": [
    {
     "type": "filter",
     "expr": "!datum.open"
    },
    {
     "type": "window",
     "sort": {
      "field": "start",
      "order": "descending"
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "m"
     ]
    }
   ]
  },
  {
   "name": "rows",
   "source": "closedAll",
   "transform": [
    {
     "type": "formula",
     "as": "y",
     "expr": "(datum.m - 1) * rowh - scrollY"
    },
    {
     "type": "filter",
     "expr": "datum.y > -rowh && datum.y < areaH"
    }
   ]
  },
  {
   "name": "sel",
   "format": {
    "property": "aggregations.e.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     },
     "aggs": {
      "e": {
       "terms": {
        "field": "tropobeat.correlation.episode.id",
        "size": 2
       }
      }
     }
    }
   }
  },
  {
   "name": "cols",
   "values": [
    {
     "label": "START",
     "x": 0
    },
    {
     "label": "STATION",
     "x": 118
    },
    {
     "label": "PEAK VERDICT",
     "x": 250
    },
    {
     "label": "DURATION",
     "x": 420
    },
    {
     "label": "LIKELY INTERFERER",
     "x": 530
    }
   ]
  }
 ],
 "marks": [
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "field": "x"
     },
     "y": {
      "value": 12
     },
     "text": {
      "signal": "datum.label == 'START' ? 'START, UTC' + timeFormat(now(), '%Z') : datum.label"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   },
   "from": {
    "data": "cols"
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "infX"
     },
     "y": {
      "value": 12
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "signal": "showInfra ? 'INFRASTRUCTURE, CARD · FRAME · INPUT' : ''"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "width"
     },
     "y": {
      "value": 12
     },
     "align": {
      "value": "right"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "signal": "showId ? 'EPISODE' : ''"
     }
    }
   }
  },
  {
   "type": "group",
   "name": "listArea",
   "encode": {
    "update": {
     "x": {
      "value": -8
     },
     "y": {
      "signal": "head + pinH"
     },
     "width": {
      "signal": "width + 16"
     },
     "height": {
      "signal": "areaH"
     },
     "clip": {
      "value": true
     },
     "fill": {
      "value": "transparent"
     }
    }
   },
   "marks": [
    {
     "type": "rect",
     "name": "row",
     "from": {
      "data": "rows"
     },
     "encode": {
      "update": {
       "x": {
        "value": 0
       },
       "x2": {
        "signal": "(width + 8) + 8"
       },
       "y": {
        "field": "y"
       },
       "height": {
        "signal": "rowh - 2"
       },
       "fill": {
        "signal": "datum.key == selected ? '#1B3042' : datum.n % 2 ? '#0F1F2C' : '#0C1A26'"
       },
       "cornerRadius": {
        "value": 4
       },
       "cursor": {
        "value": "pointer"
       },
       "tooltip": {
        "signal": "{title: (datum.station ? datum.station + ' · ' : '') + datum.lrf + ' RF ' + datum.rf + ' · ' + stateLabel[datum.state], 'Started': timeFormat(datum.start, '%d %b %Y %H:%M:%S'), 'Duration': datum.durText, 'Side A': datum.infA, 'Side B': datum.infB, 'Episode': datum.key, 'Click': 'show its timeline and decisions below'}"
       }
      },
      "hover": {
       "fill": {
        "value": "#16283A"
       }
      }
     }
    },
    {
     "type": "rect",
     "from": {
      "data": "rows"
     },
     "encode": {
      "update": {
       "x": {
        "value": 0
       },
       "width": {
        "value": 3
       },
       "y": {
        "field": "y"
       },
       "height": {
        "signal": "rowh - 2"
       },
       "fill": {
        "value": "#E4EDF3"
       },
       "opacity": {
        "signal": "datum.key == selected ? 1 : 0"
       }
      }
     }
    },
    {
     "type": "text",
     "encode": {
      "update": {
       "x": {
        "value": 8
       },
       "y": {
        "signal": "datum.y + 14"
       },
       "baseline": {
        "value": "middle"
       },
       "font": {
        "value": "ui-monospace,Menlo,Consolas,monospace"
       },
       "fontSize": {
        "value": 12
       },
       "fill": {
        "value": "#C3D1DB"
       },
       "text": {
        "signal": "upper(timeFormat(datum.start, '%d %b %H:%M'))"
       }
      }
     },
     "from": {
      "data": "rows"
     }
    },
    {
     "type": "text",
     "encode": {
      "update": {
       "x": {
        "value": 126
       },
       "y": {
        "signal": "datum.y + 14"
       },
       "baseline": {
        "value": "middle"
       },
       "fontSize": {
        "value": 14
       },
       "fontWeight": {
        "value": 600
       },
       "text": {
        "signal": "datum.station || datum.lrf + ' · RF ' + datum.rf"
       },
       "limit": {
        "value": 126
       }
      }
     },
     "from": {
      "data": "rows"
     }
    },
    {
     "type": "text",
     "encode": {
      "update": {
       "x": {
        "value": 126
       },
       "y": {
        "signal": "datum.y + 30"
       },
       "baseline": {
        "value": "middle"
       },
       "font": {
        "value": "ui-monospace,Menlo,Consolas,monospace"
       },
       "fontSize": {
        "value": 10.5
       },
       "fill": {
        "value": "#8DA2B2"
       },
       "text": {
